#!/usr/bin/env python3
"""UR-R3.5: build an evidence-bound maturity report for the 16 canonical R3 domains.

Inputs are generated by the existing exact-SHA PostgreSQL evidence verifier.
This module does not infer test outcomes from JUnit names or source code.
"""
import argparse
import hashlib
import json
from pathlib import Path

FUNCTIONAL = Path("rm-r3-functional-coverage.json")
ROLES = Path("rm-user-role-scenario-results.json")
MANIFEST = Path("rm-exact-sha-manifest.json")
CROSSWALK = Path("docs/spec/RM-R3-USER-ROLE-CROSSWALK-v1.json")
STRUCTURE = Path("rm-user-role-crosswalk-validation.json")
JSON_REPORT = Path("rm-r3-maturity-report.json")
MD_REPORT = Path("rm-r3-maturity-report.md")
RACE_PREFIX = "UR-R33-"


def require(condition, message):
    if not condition:
        raise ValueError(message)


def digest(blob):
    return hashlib.sha256(blob).hexdigest()


def read(root, path):
    raw = (root / path).read_bytes()
    return json.loads(raw), digest(raw)


def render(root):
    manifest, manifest_digest = read(root, MANIFEST)
    functional, functional_digest = read(root, FUNCTIONAL)
    roles, roles_digest = read(root, ROLES)
    crosswalk, crosswalk_digest = read(root, CROSSWALK)
    structure, structure_digest = read(root, STRUCTURE)
    sha = manifest.get("sha")
    require(isinstance(sha, str) and len(sha) == 40 and
            all(c in "0123456789abcdef" for c in sha),
            "Invalid exact commit SHA")
    require(manifest.get("qa01bGate") == "PASS" and
            manifest.get("workflowGate") == "PASS",
            "RM-QA-01B not admitted on exact SHA")
    require(manifest.get("admission") == "HOLD" and
            functional.get("productionAdmission") == "HOLD" and
            roles.get("productionAdmission") == "HOLD",
            "Production admission boundary invalid")
    require(not manifest.get("evidenceErrors"), "QA evidence errors present")
    require(functional.get("commitSha") == sha and roles.get("commitSha") == sha,
            "Cross-artifact Git SHA mismatch")
    require(functional.get("qualificationGate") == "PASS" and
            roles.get("gate") == "USER_ROLE_SERVICE_QUALIFIED",
            "Functional or role qualification not admitted")
    require(structure.get("gate") == "MAPPING_VALID_NOT_SERVICE_QUALIFIED" and
            structure.get("domains") == 16 and
            structure.get("total") == 75,
            "Unqualified or malformed crosswalk")
    require(structure.get("crosswalkSha256") == crosswalk_digest,
            "Crosswalk checksum mismatch")
    require(structure.get("catalogueSha256") == functional.get("catalogueSha256"),
            "Catalogue checksum mismatch")
    require(manifest.get("functionalCoverage", {}).get("catalogueSha256") ==
            functional.get("catalogueSha256"), "Manifest functional hash mismatch")
    role_meta = manifest.get("userRoleQualification", {})
    require(role_meta.get("catalogueSha256") == roles.get("catalogueSha256") and
            role_meta.get("gate") == roles.get("gate"),
            "Manifest role catalogue/gate mismatch")
    migration = manifest.get("migrationFingerprint")
    require(isinstance(migration, dict) and len(migration.get("sha256", "")) == 64
            and migration.get("fileCount", 0) > 0,
            "Missing Liquibase SHA-256 fingerprint")
    required = manifest.get("required", [])
    require(len(required) == 6 and len({x.get("name") for x in required}) == 6 and
            all(g.get("sha") == sha and g.get("conclusion") == "success"
                and g.get("status") == "completed" for g in required),
            "Missing same-SHA mandatory workflow")
    for gate in required:
        artifacts = gate.get("verifiedArtifacts", [])
        require(bool(artifacts) and all(len(a.get("sha256", "")) == 64 for a in artifacts),
                "Missing verified artifact digests: " + str(gate.get("name")))
    counts = manifest.get("testCounts", {})
    require(all(isinstance(counts.get(k), int) and counts[k] >= 0
                for k in ("tests", "failures", "errors", "skipped")),
            "Invalid Surefire totals")
    require(counts["tests"] > 0 and counts["failures"] == 0 and
            counts["errors"] == 0 and counts["skipped"] <= counts["tests"],
            "Test aggregation incomplete or failed")
    d = functional.get("domains")
    summary = functional.get("summary", {})
    require(isinstance(d, list) and len(d) == 16 and summary.get("domains") == 16
            and summary.get("total") == 75 and summary.get("implemented") == 46
            and summary.get("notImplemented") == 29, "Changed R3 denominator")
    require(len({x.get("id") for x in d}) == 16, "Duplicate R3 domain")
    require(summary.get("verifiedInternal") == summary.get("testExecuted") == 46,
            "Expected 46 exact-SHA verified R3 proofs")
    c = crosswalk.get("requirements")
    require(isinstance(c, list) and len(c) == 75 and
            len({x.get("requirementId") for x in c}) == 75,
            "Invalid 75-requirement crosswalk")
    require(len(crosswalk.get("actorProfileIds", [])) == 13,
            "Actor registry incomplete")
    lookup = {x["requirementId"]: x for x in c}
    cases = roles.get("cases")
    require(isinstance(cases, list) and len(cases) == 19 and
            roles.get("mandatory") == 19 and roles.get("verifiedInternal") == 19
            and roles.get("executedPostgresql") == 19 and
            len({x.get("caseId") for x in cases}) == 19,
            "Missing or duplicate mandatory role/concurrency cases")
    for case in cases:
        require(case.get("status") == "VERIFIED_INTERNAL" and case.get("executed") is True,
                "Unverified JUnit case: " + str(case.get("caseId")))
        for rid in case.get("requirementIds", []):
            require(rid in lookup and case["caseId"] in lookup[rid].get("userRoleCaseIds", []),
                    "Role case not connected to crosswalk: " + str(case.get("caseId")))
    race = [x for x in cases if x["caseId"].startswith(RACE_PREFIX)]
    require(len(race) == 8, "Incomplete R3.3 concurrent and rollback cases")
    rows = []
    domain_ids = set()
    all_ids = set()
    for domain in d:
        did = domain["id"]
        domain_ids.add(did)
        requirements = domain.get("requirements")
        require(isinstance(requirements, list) and requirements, "Empty R3 domain: " + did)
        ids = {x["id"] for x in requirements}
        require(len(ids) == len(requirements) and not (all_ids & ids),
                "Duplicate R3 requirement")
        all_ids.update(ids)
        require(all(lookup.get(rid, {}).get("domainId") == did for rid in ids),
                "Crosswalk/domain mismatch: " + did)
        count = len(requirements)
        implemented = sum(x.get("delivery") == "IMPLEMENTED" for x in requirements)
        verified = sum(x.get("status") == "VERIFIED_INTERNAL" for x in requirements)
        require((count == domain.get("total") and implemented == domain.get("implemented")
                 and verified == domain.get("verifiedInternal")
                 and verified <= implemented and domain.get("notImplemented") == count - implemented),
                "Domain evidence totals mismatch: " + did)
        linked = [x for x in cases if ids.intersection(x["requirementIds"])]
        linked_race = [x for x in race if ids.intersection(x["requirementIds"])]
        linked_case_ids = {x["caseId"] for x in linked}
        linked_race_ids = {x["caseId"] for x in linked_race}
        # 'not assessed' is distinct from "0% passed" for domains with no role tests.
        rows.append({
            "domainId": did,
            "domainName": domain["name"],
            "requirements": count,
            "implemented": implemented,
            "planned": count - implemented,
            "verifiedCapabilities": verified,
            "implementationPct": round(100 * implemented / count, 2),
            "verifiedCapabilityPct": round(100 * verified / count, 2),
            "roleCaseCoverage": {
                "status": "VERIFIED" if linked_case_ids else "NOT_ASSESSED",
                "required": len(linked_case_ids),
                "verified": len(linked_case_ids),
                "caseIds": sorted(linked_case_ids),
            },
            "concurrencyCoverage": {
                "status": "VERIFIED" if linked_race_ids else "NOT_ASSESSED",
                "required": len(linked_race_ids),
                "verified": len(linked_race_ids),
                "caseIds": sorted(linked_race_ids),
            },
            "unimplementedIds": sorted(x["id"] for x in requirements
                                       if x.get("delivery") == "PLANNED"),
            "qualification": "INTERNAL_SERVICE_EVIDENCE",
            "productionAdmission": "HOLD",
        })
    require(len(all_ids) == 75 and set(lookup) == all_ids and len(domain_ids) == 16,
            "Unmatched functional requirement rows")
    report = {
        "schema": "RM-UR-R3.5-MATURITY/v1",
        "gitSha": sha,
        "branch": manifest.get("branch"),
        "scope": "Curated R3-v1 first wave; not full CRM/ERP product readiness",
        "evidenceGate": "PASS",
        "roleServiceGate": roles["gate"],
        "productionAdmission": "HOLD",
        "releaseReadiness": "NOT_ADMITTED",
        "warning": "A domain without registered role or concurrency cases is NOT_ASSESSED, not 100% covered",
        "sources": {
            "qaManifestSha256": manifest_digest,
            "functionalReportSha256": functional_digest,
            "roleReportSha256": roles_digest,
            "crosswalkSha256": crosswalk_digest,
            "crosswalkValidationSha256": structure_digest,
            "catalogueSha256": functional["catalogueSha256"],
            "roleCatalogueSha256": roles["catalogueSha256"],
            "liquibaseFingerprint": migration["sha256"],
        },
        "summary": {
            "domains": 16,
            "totalRequirements": 75,
            "implemented": 46,
            "verifiedCapabilities": 46,
            "planned": 29,
            "implementationPct": round(46 / 75 * 100, 2),
            "verifiedCapabilityPct": round(46 / 75 * 100, 2),
            "mandatoryRoleCases": 19,
            "verifiedRoleCases": 19,
            "mandatoryConcurrencyCases": 8,
            "verifiedConcurrencyCases": 8,
            "testExecutions": counts["tests"],
            "failedExecutions": counts["failures"] + counts["errors"],
            "skippedExecutions": counts["skipped"],
            "notRoleAssessedDomains": sum(not x["roleCaseCoverage"]["required"] for x in rows),
            "notConcurrencyAssessedDomains": sum(not x["concurrencyCoverage"]["required"] for x in rows),
        },
        "domains": rows,
    }
    return report


def markdown(report):
    s = report["summary"]
    lines = [
        "# RM — Unified maturity report (UR-R3.5)", "",
        "**Exact SHA:** `" + report["gitSha"] + "` | **RM-QA-01B:** PASS | **Production:** HOLD", "",
        "Scope: **75 R3-v1 requirements, 16 assessment domains**. This is internal service",
        "qualification, NOT product completeness, independent security approval, user OIDC E2E or release admission.", "",
        "Functional: **46/75 implemented (61.33%)**, **46/75 exact-SHA verified (61.33%)**, **29 planned**.",
        "User-role/JUnit: **19/19 mandatory cases**, concurrency/rollback/retry **8/8**.",
        "Each case is counted once in global totals, even if mapped to multiple domains.",
        "Domain counts of associated cases are NOT additive between domains.", "",
        "| Domain | Implemented | Verified R3 | Planned | Role cases | Race/rollback cases |",
        "|---|---:|---:|---:|---|---|",
    ]
    for x in report["domains"]:
        role, race = x["roleCaseCoverage"], x["concurrencyCoverage"]
        def cell(v):
            return (str(v["verified"]) + "/" + str(v["required"])
                    if v["required"] else "NOT_ASSESSED")
        lines.append("| " + x["domainName"] + " | " + str(x["implemented"]) + "/" +
                     str(x["requirements"]) + " | " + str(x["verifiedCapabilities"]) +
                     "/" + str(x["requirements"]) + " | " + str(x["planned"]) +
                     " | " + cell(role) + " | " + cell(race) + " |")
    lines += [
        "", "## Evidence trust boundary", "",
        "- Source JSON files are generated by the existing mandatory exact-SHA Surefire validator.",
        "- Report checks their same Git SHA, catalogue/crosswalk hashes, approved manifest,",
        "  artifact SHA-256, Liquibase fingerprint, totals and all 19 JUnit case mappings.",
        "- **NOT_ASSESSED** marks domains without mapped role or concurrency tests; it is not a pass.",
        "- Tests repeated across workflows do not increase unique capabilities or role scenarios.",
        "- **PRODUCTION HOLD** remains in force irrespective of passing internal QA.",
        "", "## Missing capabilities by domain", ""
    ]
    for x in report["domains"]:
        if x["unimplementedIds"]:
            lines.append("- **" + x["domainName"] + "**: " + ", ".join(x["unimplementedIds"]))
    lines += ["", "JSON source: `rm-r3-maturity-report.json`.", ""]
    return "\n".join(lines)


def generate(root):
    report = render(root)
    (root / JSON_REPORT).write_text(json.dumps(report, indent=2, ensure_ascii=False) + "\n",
                                    encoding="utf-8")
    (root / MD_REPORT).write_text(markdown(report), encoding="utf-8")
    return report


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[2])
    args = parser.parse_args()
    result = generate(args.root)
    print(json.dumps({"gate": result["evidenceGate"], "sha": result["gitSha"],
                      "summary": result["summary"]}, indent=2))
